export class DynamicTradeOffAnalysis {
  constructor() {
    this.history = [];
  }

  evaluateUpgrade(upgradeProposal) {
    const computationalCost = upgradeProposal.estimatedCost;
    const systemBenefit = upgradeProposal.expectedBenefit;
    const tradeOffScore = systemBenefit / computationalCost;
    
    this.history.push({ upgradeProposal, tradeOffScore });
    return tradeOffScore > 1 ? 'Approve' : 'Reject';
  }
}